#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;
typedef vector<ll> vl;
int main(void)
{
    ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
    const ll maxn = 5e5 + 10;
    ll n, m;
    ll a[maxn], b[maxn];
    ll A[2], B[2], C[2];
    cin >> n >> m;
    for (ll i = 1; i <= n; i++) cin >> a[i];
    for (ll i = 1; i <= m; i++) cin >> b[i];
    sort(a + 1, a + n + 1);
    sort(b + 1, b + m + 1);
    ll ans = 0;
    if (n & 1) for (ll i = 1; i <= m; i++) ans += b[i];
    if (m & 1) for (ll i = 1; i <= n; i++) ans += a[i];
    n -= n % 2, m -= m % 2;
    vector<pair<ll, ll>> vec;
    for (ll i = 1; i <= n; i++)
        vec.push_back({2 * a[i], 0});
    for (ll i = 1; i <= m; i++)
        vec.push_back({2 * b[i], 1});
    sort(vec.begin(), vec.end(), greater<pair<ll, ll>>());
    A[0] = n / 2;
    A[1] = m / 2;
    for (auto p : vec)
    {
        if (A[p.second] > 0)
        {
            A[p.second]--;
            C[p.second]++;
            ans += B[p.second ^ 1] * p.first;
        }
        else
        {
            B[p.second]++;
            ans += C[p.second ^ 1] * p.first;
        }
    }
    cout << ans << '\n';
}
